import React, { useState, useEffect } from 'react';
import { 
  Grid, 
  Paper, 
  Typography, 
  Box, 
  Card, 
  CardContent,
  CardHeader,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Button,
  Skeleton
} from '@mui/material';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import InventoryIcon from '@mui/icons-material/Inventory';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import ReceiptIcon from '@mui/icons-material/Receipt';
import { Link as RouterLink } from 'react-router-dom';
import { formatCurrency, formatDate } from '../../../shared/utils/formatters';
import useSalesDashboard from '../hooks/useSalesDashboard';

// Componente de tarjeta de resumen
const SummaryCard = ({ title, value, icon, color, loading, change, period }) => (
  <Card sx={{ height: '100%' }}>
    <CardContent>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
        <Typography variant="h6" component="div" color="text.secondary">
          {title}
        </Typography>
        <Box sx={{ 
          backgroundColor: `${color}.light`, 
          color: `${color}.main`,
          borderRadius: '50%',
          width: 40,
          height: 40,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}>
          {icon}
        </Box>
      </Box>
      
      {loading ? (
        <Skeleton variant="rectangular" width="60%" height={40} />
      ) : (
        <Typography variant="h4" component="div">
          {value}
        </Typography>
      )}
      
      {change && (
        <Box sx={{ display: 'flex', alignItems: 'center', mt: 1 }}>
          {change > 0 ? (
            <ArrowUpwardIcon fontSize="small" color="success" />
          ) : (
            <ArrowDownwardIcon fontSize="small" color="error" />
          )}
          <Typography 
            variant="body2" 
            color={change > 0 ? 'success.main' : 'error.main'}
            sx={{ ml: 0.5 }}
          >
            {Math.abs(change)}% vs {period}
          </Typography>
        </Box>
      )}
    </CardContent>
  </Card>
);

// Componente de lista de actividad reciente
const RecentActivityList = ({ activities, loading }) => (
  <List>
    {loading ? (
      Array.from(new Array(5)).map((_, index) => (
        <ListItem key={index} divider>
          <Skeleton variant="rectangular" width="100%" height={40} />
        </ListItem>
      ))
    ) : activities.length > 0 ? (
      activities.map((activity, index) => (
        <ListItem key={index} divider>
          <ListItemIcon>
            {activity.type === 'sale' && <ReceiptIcon color="success" />}
            {activity.type === 'purchase' && <ShoppingCartIcon color="primary" />}
            {activity.type === 'inventory' && <InventoryIcon color="warning" />}
          </ListItemIcon>
          <ListItemText 
            primary={activity.description}
            secondary={formatDate(activity.date)}
          />
        </ListItem>
      ))
    ) : (
      <ListItem>
        <ListItemText primary="No hay actividades recientes" />
      </ListItem>
    )}
  </List>
);

const SalesDashboard = () => {
  const { 
    dashboardData, 
    recentActivities, 
    lowStockItems, 
    pendingOrders,
    loading 
  } = useSalesDashboard();
  
  return (
    <Grid container spacing={3}>
      {/* Tarjetas de resumen */}
      <Grid item xs={12} md={6} lg={3}>
        <SummaryCard 
          title="Ventas Totales"
          value={formatCurrency(dashboardData.totalSales)}
          icon={<ReceiptIcon />}
          color="success"
          loading={loading}
          change={dashboardData.salesChange}
          period="mes anterior"
        />
      </Grid>
      
      <Grid item xs={12} md={6} lg={3}>
        <SummaryCard 
          title="Compras Totales"
          value={formatCurrency(dashboardData.totalPurchases)}
          icon={<ShoppingCartIcon />}
          color="primary"
          loading={loading}
          change={dashboardData.purchasesChange}
          period="mes anterior"
        />
      </Grid>
      
      <Grid item xs={12} md={6} lg={3}>
        <SummaryCard 
          title="Margen Bruto"
          value={`${dashboardData.grossMargin}%`}
          icon={<ArrowUpwardIcon />}
          color="info"
          loading={loading}
          change={dashboardData.marginChange}
          period="mes anterior"
        />
      </Grid>
      
      <Grid item xs={12} md={6} lg={3}>
        <SummaryCard 
          title="Valor de Inventario"
          value={formatCurrency(dashboardData.inventoryValue)}
          icon={<InventoryIcon />}
          color="warning"
          loading={loading}
        />
      </Grid>
      
      {/* Actividad reciente */}
      <Grid item xs={12} md={6}>
        <Paper sx={{ p: 0, height: '100%' }}>
          <CardHeader 
            title="Actividad Reciente" 
            action={
              <Button 
                component={RouterLink} 
                to="/ventas/ventas" 
                size="small"
              >
                Ver todo
              </Button>
            }
          />
          <Divider />
          <Box sx={{ p: 0 }}>
            <RecentActivityList 
              activities={recentActivities} 
              loading={loading} 
            />
          </Box>
        </Paper>
      </Grid>
      
      {/* Productos con bajo stock */}
      <Grid item xs={12} md={6}>
        <Paper sx={{ p: 0, height: '100%' }}>
          <CardHeader 
            title="Productos con Bajo Stock" 
            action={
              <Button 
                component={RouterLink} 
                to="/ventas/inventario" 
                size="small"
              >
                Ver inventario
              </Button>
            }
          />
          <Divider />
          <List>
            {loading ? (
              Array.from(new Array(5)).map((_, index) => (
                <ListItem key={index} divider>
                  <Skeleton variant="rectangular" width="100%" height={40} />
                </ListItem>
              ))
            ) : lowStockItems.length > 0 ? (
              lowStockItems.map((item, index) => (
                <ListItem key={index} divider>
                  <ListItemIcon>
                    <InventoryIcon color="error" />
                  </ListItemIcon>
                  <ListItemText 
                    primary={item.name}
                    secondary={`Stock actual: ${item.currentStock} (Mínimo: ${item.minStock})`}
                  />
                </ListItem>
              ))
            ) : (
              <ListItem>
                <ListItemText primary="No hay productos con bajo stock" />
              </ListItem>
            )}
          </List>
        </Paper>
      </Grid>
      
      {/* Órdenes pendientes */}
      <Grid item xs={12}>
        <Paper sx={{ p: 0 }}>
          <CardHeader 
            title="Órdenes Pendientes" 
            action={
              <Button 
                component={RouterLink} 
                to="/ventas/compras" 
                size="small"
              >
                Ver todas
              </Button>
            }
          />
          <Divider />
          <Box sx={{ overflowX: 'auto' }}>
            {loading ? (
              <Box sx={{ p: 2 }}>
                <Skeleton variant="rectangular" width="100%" height={200} />
              </Box>
            ) : pendingOrders.length > 0 ? (
              <List>
                {pendingOrders.map((order, index) => (
                  <ListItem key={index} divider>
                    <Grid container spacing={2}>
                      <Grid item xs={12} sm={3}>
                        <Typography variant="subtitle2">
                          Orden #{order.reference}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {formatDate(order.date)}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} sm={3}>
                        <Typography variant="body2">
                          Proveedor: {order.supplier}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} sm={3}>
                        <Typography variant="body2">
                          Estado: {order.status === 'pending' ? 'Pendiente' : 'En proceso'}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} sm={3}>
                        <Typography variant="body2" align="right">
                          Total: {formatCurrency(order.total)}
                        </Typography>
                      </Grid>
                    </Grid>
                  </ListItem>
                ))}
              </List>
            ) : (
              <Box sx={{ p: 2, textAlign: 'center' }}>
                <Typography>No hay órdenes pendientes</Typography>
              </Box>
            )}
          </Box>
        </Paper>
      </Grid>
    </Grid>
  );
};

export default SalesDashboard;