import { useState, useEffect, useCallback } from 'react';
import salesDashboardService from '../services/salesDashboardService';

const useSalesDashboard = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [dashboardData, setDashboardData] = useState({
    totalSales: 0,
    totalPurchases: 0,
    grossMargin: 0,
    inventoryValue: 0,
    salesChange: 0,
    purchasesChange: 0,
    marginChange: 0
  });
  const [recentActivities, setRecentActivities] = useState([]);
  const [lowStockItems, setLowStockItems] = useState([]);
  const [pendingOrders, setPendingOrders] = useState([]);
  
  const loadDashboardData = useCallback(async () => {
    setLoading(true);
    setError(null);
    
    try {
      // En un entorno real, estas serían llamadas a la API
      const dashboardResponse = await salesDashboardService.getDashboardSummary();
      const activitiesResponse = await salesDashboardService.getRecentActivities();
      const stockResponse = await salesDashboardService.getLowStockItems();
      const ordersResponse = await salesDashboardService.getPendingOrders();
      
      setDashboardData(dashboardResponse);
      setRecentActivities(activitiesResponse);
      setLowStockItems(stockResponse);
      setPendingOrders(ordersResponse);
    } catch (err) {
      console.error('Error loading dashboard data:', err);
      setError(err.message || 'Error al cargar los datos del dashboard');
    } finally {
      setLoading(false);
    }
  }, []);
  
  useEffect(() => {
    loadDashboardData();
    
    // Actualizar datos cada 5 minutos
    const intervalId = setInterval(loadDashboardData, 5 * 60 * 1000);
    
    return () => clearInterval(intervalId);
  }, [loadDashboardData]);
  
  return {
    loading,
    error,
    dashboardData,
    recentActivities,
    lowStockItems,
    pendingOrders,
    refreshData: loadDashboardData
  };
};

export default useSalesDashboard;